        Q = deque([(start_r, start_c)])
        VISITED = [(start_r, start_c)]
        visited_reg[start_r][start_c] = True

        while Q:
            r, c = Q.popleft()
            for dr, dc in DIRS:
                nr, nc = r + dr, c + dc
                if 0 <= nr < 15 and 0 <= nc < 15 and (nr, nc) not in VISITED:
                    if input_grid[nr][nc] in [3, 9]:
                        VISITED.append((nr, nc))
                        visited_reg[nr][nc] = True
                        Q.append((nr, nc))

        regions.append(VISITED)

